//! `LightBrowser.humanMove` / `humanClick` / `humanType` / `humanScroll`:
//! input generated by lb-behavior and replayed through the trusted input
//! pipeline ([`super::input`]) on the page's worker.
//!
//! - Profile and seed come from the persona ([`behavior_for`]): the preset
//!   named by `behavior.profile`, the scroll device from
//!   `behavior.pointing_device` (default: trackpad on macOS, notched wheel
//!   elsewhere) and `behavior.seed` (default: a hash of the persona id and
//!   fingerprint seeds). Call `n` on a page uses `mix_seed(seed, n)`, so the
//!   same persona and the same calls give the same event streams.
//! - Timing: events are dispatched at their offsets from the start of the
//!   call with `tokio::time::sleep_until` on the page's worker, which keeps
//!   serving other pages meanwhile. With virtual time the clock is advanced
//!   to each event's time instead of sleeping.
//! - The pointer position persists per page (across navigations, like the
//!   OS cursor), also following `Input.dispatchMouseEvent`. Before the first
//!   input it is a seeded point in the upper middle of the viewport.
//! - Selectors are resolved in the main document from Rust; no script runs
//!   in any world. A target outside the viewport is first scrolled into view
//!   with wheel input. Calls on one page run one after another.

use std::rc::Rc;
use std::time::Duration;

use lb_behavior::cdp::{CdpInputCommand, CdpOptions, events_to_cdp_with};
use lb_behavior::rng::{mix_seed, seed_from_bytes, seeded_rng, uniform};
use lb_behavior::{
    BehaviorProfile, Button, ClickOptions, InputEvent, Point, ScrollDirection, ScrollType,
    TargetBox,
};
use lb_cdp::types::{
    HumanClick, HumanCommand, HumanMove, HumanScroll, HumanType, KeyEvent, MouseEvent,
};
use lb_cdp::{HostError, HostResult};
use lb_dom::NodeId;
use lb_persona::PersonaProfile;
use lb_webapi::rt::Window;
use serde_json::{Value, json};

use super::agent::{Agent, DOCUMENT};
use crate::browser::WorkerState;
use crate::page::PageState;

/// Per-page state, kept on the page's agent.
#[derive(Default)]
pub(crate) struct HumanState {
    /// Last pointer position (viewport CSS px).
    pub pointer: Option<(f64, f64)>,
    /// Number of human calls so far (seed index).
    pub calls: u64,
    /// Serialises human calls on one page.
    pub lock: Rc<tokio::sync::Mutex<()>>,
}

/// The behaviour profile and root seed of a persona.
pub fn behavior_for(persona: &PersonaProfile) -> (BehaviorProfile, u64) {
    let b = &persona.behavior;
    let profile = BehaviorProfile::preset(&b.profile).unwrap_or_else(BehaviorProfile::casual_user);
    let mac = persona.os_kind() == lb_persona::OsKind::MacOs;
    let device = b
        .pointing_device
        .as_deref()
        .unwrap_or(if mac { "trackpad" } else { "mouse" });
    let mut profile = profile.with_scroll_type(if device == "trackpad" {
        ScrollType::Trackpad
    } else {
        ScrollType::Wheel
    });
    // The OS's wheel detent (Windows 100 px, Linux 120, macOS 40 with
    // acceleration); `wheelDelta` follows from it in lb-webapi.
    profile.scroll.notch_px = persona.wheel().px_per_notch;
    profile.scroll.accelerate = mac;
    let seed = b
        .seed
        .as_deref()
        .and_then(|s| u64::from_str_radix(s, 16).ok())
        .unwrap_or_else(|| {
            let f = &persona.fingerprint_seeds;
            seed_from_bytes(
                format!(
                    "{}|{}|{}|{}",
                    persona.profile_id, f.canvas_seed, f.webgl_noise_seed, f.audio_seed
                )
                .as_bytes(),
            )
        });
    // Per-key habits stay the same for the whole session.
    profile.keyboard.key_seed = seed;
    (profile, seed)
}

fn closed() -> HostError {
    HostError::new("Target closed")
}

/// Runs one human command on the page's worker.
pub(super) async fn run(
    ws: Rc<WorkerState>,
    p: Rc<PageState>,
    cmd: HumanCommand,
) -> HostResult<Value> {
    let agent = p.agent().ok_or_else(closed)?;
    let lock = agent.st.borrow().human.lock.clone();
    let _turn = lock.lock().await;
    let (profile, seed) = match p.ctx.profile() {
        Some(pp) => behavior_for(pp),
        None => (BehaviorProfile::casual_user(), 0),
    };
    let h = Human {
        ws,
        p,
        agent,
        profile,
        seed,
    };
    match cmd {
        HumanCommand::Move(m) => h.do_move(m).await.map(|()| json!({})),
        HumanCommand::Click(c) => h.click(&c).await.map(|pt| json!({"x": pt.x, "y": pt.y})),
        HumanCommand::Type(t) => h.type_text(&t).await.map(|()| json!({})),
        HumanCommand::Scroll(s) => h.scroll(&s).await.map(|()| json!({})),
    }
}

struct Human {
    ws: Rc<WorkerState>,
    p: Rc<PageState>,
    agent: Rc<Agent>,
    profile: BehaviorProfile,
    seed: u64,
}

impl Human {
    fn window(&self) -> HostResult<Rc<Window>> {
        self.p.window().ok_or_else(closed)
    }

    fn viewport(&self) -> HostResult<(f64, f64)> {
        let w = self.window()?;
        let (vw, vh) = w.with_layout_engine(|l, _| l.viewport());
        Ok((f64::from(vw).max(1.0), f64::from(vh).max(1.0)))
    }

    fn next_seed(&self) -> u64 {
        let mut st = self.agent.st.borrow_mut();
        let n = st.human.calls;
        st.human.calls += 1;
        mix_seed(self.seed, n)
    }

    /// The pointer, inside the viewport.
    fn pointer(&self) -> HostResult<Point> {
        let (vw, vh) = self.viewport()?;
        let stored = self.agent.st.borrow().human.pointer;
        let (x, y) = stored.unwrap_or_else(|| {
            let mut rng = seeded_rng(mix_seed(self.seed, u64::MAX));
            (
                (vw * uniform(&mut rng, 0.3, 0.7)).round(),
                (vh * uniform(&mut rng, 0.2, 0.55)).round(),
            )
        });
        Ok(Point::new(
            x.clamp(0.0, (vw - 1.0).max(0.0)),
            y.clamp(0.0, (vh - 1.0).max(0.0)),
        ))
    }

    /// Dispatch `events` at their offsets from now.
    async fn replay(&self, events: &[InputEvent]) -> HostResult<()> {
        let start_pointer = self.pointer()?;
        let cmds = events_to_cdp_with(
            events,
            &CdpOptions {
                initial_pointer: (start_pointer.x, start_pointer.y),
            },
        );
        let w = self.window()?;
        let virtual_time = w.clock.is_virtual();
        let (origin, base) = (w.clock.time_origin, w.clock.now());
        let start = tokio::time::Instant::now();
        for c in cmds {
            let ts = if virtual_time {
                Some((origin + base + c.offset_ms as f64) / 1000.0)
            } else {
                tokio::time::sleep_until(start + Duration::from_millis(c.offset_ms)).await;
                None
            };
            let params = c.command.params();
            let bad = |e: serde_json::Error| HostError::new(format!("bad input event: {e}"));
            match &c.command {
                CdpInputCommand::DispatchMouseEvent(_) => {
                    let mut ev: MouseEvent = serde_json::from_value(params).map_err(bad)?;
                    ev.timestamp = ts;
                    super::input::mouse(&self.ws, &self.p, ev)?;
                }
                CdpInputCommand::DispatchKeyEvent(_) => {
                    let mut ev: KeyEvent = serde_json::from_value(params).map_err(bad)?;
                    ev.timestamp = ts;
                    super::input::key(&self.ws, &self.p, ev)?;
                }
                CdpInputCommand::InsertText(t) => super::input::text(&self.ws, &self.p, &t.text)?,
            }
        }
        Ok(())
    }

    /// The element for `selector` in the main document and its box.
    fn element(&self, selector: &str) -> HostResult<(NodeId, TargetBox)> {
        let w = self.window()?;
        let node = w
            .with_doc(|d| d.query_selector(DOCUMENT, selector))
            .map_err(|_| HostError::new(format!("'{selector}' is not a valid selector")))?
            .ok_or_else(|| HostError::new(format!("No node found for selector: {selector}")))?;
        let (visible, r) =
            w.with_layout_engine(|l, d| (l.is_visible(d, node), l.bounding_client_rect(d, node)));
        if !visible || r.width <= 0.0 || r.height <= 0.0 {
            return Err(HostError::new("Node is not visible"));
        }
        Ok((
            node,
            TargetBox::new(
                f64::from(r.x),
                f64::from(r.y),
                f64::from(r.width),
                f64::from(r.height),
            ),
        ))
    }

    /// The box's centre is comfortably inside the viewport.
    fn in_view(&self, b: &TargetBox) -> HostResult<bool> {
        let (vw, vh) = self.viewport()?;
        let c = b.center();
        let my = (vh * 0.05).min(40.0);
        Ok(c.x >= 0.0 && c.x <= vw && c.y >= my && c.y <= vh - my)
    }

    /// Wheel input until `selector`'s element is in view; returns its box.
    async fn scroll_into_view(&self, selector: &str) -> HostResult<TargetBox> {
        let (_, mut b) = self.element(selector)?;
        for _ in 0..4 {
            if self.in_view(&b)? {
                return Ok(b);
            }
            let (vw, vh) = self.viewport()?;
            let w = self.window()?;
            let ((sx, sy), (dw, dh)) =
                w.with_layout_engine(|l, d| (l.window_scroll(d), l.document_size(d)));
            let (sx, sy, dw, dh) = (f64::from(sx), f64::from(sy), f64::from(dw), f64::from(dh));
            // Where the user wants the element: the upper middle of the
            // viewport.
            let mut rng = seeded_rng(mix_seed(
                self.seed ^ 0x5c,
                self.agent.st.borrow().human.calls,
            ));
            let c = b.center();
            let want_y = vh * uniform(&mut rng, 0.3, 0.6);
            let dy = (sy + c.y - want_y).clamp(0.0, (dh - vh).max(0.0)) - sy;
            let dx = if c.x < 0.0 || c.x > vw {
                (sx + c.x - vw / 2.0).clamp(0.0, (dw - vw).max(0.0)) - sx
            } else {
                0.0
            };
            if dy.abs() < 1.0 && dx.abs() < 1.0 {
                break;
            }
            self.wheel(dx, dy).await?;
            b = self.element(selector)?.1;
        }
        if self.in_view(&b)? {
            Ok(b)
        } else {
            // Clicking still works when any part of the box is visible.
            let (vw, vh) = self.viewport()?;
            let visible = b.x < vw && b.y < vh && b.x + b.width > 0.0 && b.y + b.height > 0.0;
            if visible {
                Ok(b)
            } else {
                Err(HostError::new("Node is not visible"))
            }
        }
    }

    /// Wheel input for (dx, dy) at the pointer.
    async fn wheel(&self, dx: f64, dy: f64) -> HostResult<()> {
        let mut events = Vec::new();
        if dy.abs() >= 0.5 {
            let dir = if dy > 0.0 {
                ScrollDirection::Down
            } else {
                ScrollDirection::Up
            };
            events.extend(lb_behavior::human_scroll_events(
                dir,
                dy.abs(),
                &self.profile,
                self.next_seed(),
            ));
        }
        if dx.abs() >= 0.5 {
            let dir = if dx > 0.0 {
                ScrollDirection::Right
            } else {
                ScrollDirection::Left
            };
            events.extend(lb_behavior::human_scroll_events(
                dir,
                dx.abs(),
                &self.profile,
                self.next_seed(),
            ));
        }
        self.replay(&events).await
    }

    async fn do_move(&self, m: HumanMove) -> HostResult<()> {
        if !m.x.is_finite() || !m.y.is_finite() {
            return Err(HostError::new("x and y must be finite numbers"));
        }
        let from = self.pointer()?;
        let events = lb_behavior::human_move_events(
            from,
            Point::new(m.x, m.y),
            &self.profile,
            self.next_seed(),
        );
        self.replay(&events).await
    }

    async fn click(&self, c: &HumanClick) -> HostResult<Point> {
        let target = match (&c.selector, c.x, c.y) {
            (Some(sel), _, _) => self.scroll_into_view(sel).await?,
            (None, Some(x), Some(y)) if x.is_finite() && y.is_finite() => {
                // A point: aim within a few pixels of it.
                TargetBox::around(Point::new(x, y), 8.0)
            }
            _ => return Err(HostError::new("selector or both x and y are required")),
        };
        let opts = ClickOptions {
            button: match c.button.as_deref() {
                Some("right") => Button::Right,
                Some("middle") => Button::Middle,
                _ => Button::Left,
            },
            click_count: c.click_count.unwrap_or(1).clamp(1, 3),
        };
        let from = self.pointer()?;
        let (events, at) = lb_behavior::human_click_box_events(
            from,
            &target,
            opts,
            &self.profile,
            self.next_seed(),
        );
        self.replay(&events).await?;
        Ok(at)
    }

    async fn type_text(&self, t: &HumanType) -> HostResult<()> {
        if let Some(sel) = &t.selector {
            self.click(&HumanClick {
                selector: Some(sel.clone()),
                ..Default::default()
            })
            .await?;
        }
        let events = lb_behavior::human_type_events(&t.text, &self.profile, self.next_seed());
        self.replay(&events).await
    }

    async fn scroll(&self, s: &HumanScroll) -> HostResult<()> {
        if let (Some(x), Some(y)) = (s.x, s.y) {
            self.do_move(HumanMove { x, y }).await?;
        }
        if let Some(sel) = &s.selector {
            self.scroll_into_view(sel).await?;
            return Ok(());
        }
        self.wheel(s.delta_x, s.delta_y).await
    }
}
